  WHERE m.machine_class = v.machine_class
    AND m.location = v.location
    AND lower(trim(m.machine_name)) = lower(trim(v.machine_name))
);

-- ── 2. Catalog rows (migration 792): machine_class, where still NULL.
UPDATE process_taxonomy pt
SET machine_class = v.machine_class
FROM (VALUES
  ($str$Hydroform$str$, $str$hydroform$str$),
  ($str$Offline Blank$str$, $str$hydroform_offline_blank$str$)
) AS v(process_name, machine_class)
WHERE pt.process_group = 'Sheet Metal - Hydroforming' AND pt.process_name = v.process_name AND pt.machine_class IS NULL;

UPDATE process_calculator_mappings pcm
SET machine_class = v.machine_class, updated_at = now()
FROM (VALUES
  ($str$Hydroform$str$, $str$hydroform$str$),
  ($str$Offline Blank$str$, $str$hydroform_offline_blank$str$)
) AS v(operation, machine_class)
WHERE pcm.process_group = 'Sheet Metal - Hydroforming' AND pcm.operation = v.operation AND pcm.machine_class IS NULL;

NOTIFY pgrst, 'reload schema';
